// Asteroid Miner – concise canvas game
// Target canvas element with id="game"

(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return console.error('Canvas with id "game" not found');
  const ctx = canvas.getContext('2d');
  const W = canvas.width = canvas.clientWidth || 800;
  const H = canvas.height = canvas.clientHeight || 600;

  // ---- Game state -----------------------------------------------------
  const ship = {
    x: 100,
    y: H / 2,
    angle: 0, // radians, 0 pointing right
    vx: 0,
    vy: 0,
    radius: 15,
    thrust: 0.2,
    turnSpeed: 0.07,
    fuel: 100,
  };

  const asteroids = [];
  const keys = {};
  let score = 0;
  let laser = false;
  let gameOver = false;

  // ---- Input ----------------------------------------------------------
  window.addEventListener('keydown', e => keys[e.code] = true);
  window.addEventListener('keyup', e => keys[e.code] = false);

  // ---- Helpers --------------------------------------------------------
  const rand = (min, max) => Math.random() * (max - min) + min;
  const dist = (a, b) => Math.hypot(a.x - b.x, a.y - b.y);

  // ---- Game loop ------------------------------------------------------
  function update(dt) {
    if (gameOver) return;
    // Ship controls
    if (keys['ArrowLeft']) ship.angle -= ship.turnSpeed;
    if (keys['ArrowRight']) ship.angle += ship.turnSpeed;
    if (keys['ArrowUp'] && ship.fuel > 0) {
      ship.vx += Math.cos(ship.angle) * ship.thrust;
      ship.vy += Math.sin(ship.angle) * ship.thrust;
      ship.fuel -= 0.05; // consume fuel per thrust frame
    }
    laser = !!keys['Space'];

    // Apply inertia (simple drag)
    ship.vx *= 0.99;
    ship.vy *= 0.99;
    ship.x += ship.vx;
    ship.y += ship.vy;

    // Keep ship inside canvas (wrap horizontally, bounce vertically)
    if (ship.x > W) ship.x = 0;
    if (ship.x < 0) ship.x = W;
    if (ship.y > H) ship.y = H;
    if (ship.y < 0) ship.y = 0;

    // Generate asteroids
    if (Math.random() < 0.02) {
      const size = rand(10, 30);
      asteroids.push({
        x: W + size,
        y: rand(0, H),
        radius: size,
        speed: rand(1, 3),
      });
    }

    // Update asteroids
    for (let i = asteroids.length - 1; i >= 0; i--) {
      const a = asteroids[i];
      a.x -= a.speed;
      // Remove when off‑screen
      if (a.x + a.radius < 0) asteroids.splice(i, 1);
    }

    // Collision & mining
    for (let i = asteroids.length - 1; i >= 0; i--) {
      const a = asteroids[i];
      const d = dist(ship, a);
      // Collision – end game
      if (d < ship.radius + a.radius) {
        gameOver = true;
        break;
      }
      // Mining laser
      if (laser && d < ship.radius + a.radius + 20) {
        score += Math.floor(a.radius);
        ship.fuel = Math.min(100, ship.fuel + a.radius * 0.2);
        // small explosion effect – just remove asteroid
        asteroids.splice(i, 1);
      }
    }

    // Fuel depletion win/lose
    if (ship.fuel <= 0) gameOver = true;
  }

  function draw() {
    // clear
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, W, H);

    // ship
    ctx.save();
    ctx.translate(ship.x, ship.y);
    ctx.rotate(ship.angle);
    ctx.fillStyle = '#0f0';
    ctx.beginPath();
    ctx.moveTo(20, 0);
    ctx.lineTo(-10, -10);
    ctx.lineTo(-10, 10);
    ctx.closePath();
    ctx.fill();
    ctx.restore();

    // asteroids
    ctx.fillStyle = '#888';
    asteroids.forEach(a => {
      ctx.beginPath();
      ctx.arc(a.x, a.y, a.radius, 0, Math.PI * 2);
      ctx.fill();
    });

    // laser visual
    if (laser) {
      ctx.strokeStyle = '#ff0';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(ship.x, ship.y);
      const lx = ship.x + Math.cos(ship.angle) * 40;
      const ly = ship.y + Math.sin(ship.angle) * 40;
      ctx.lineTo(lx, ly);
      ctx.stroke();
    }

    // UI – score, fuel
    ctx.fillStyle = '#fff';
    ctx.font = '16px sans-serif';
    ctx.fillText(`Score: ${score}`, 10, 20);
    ctx.fillText(`Fuel: ${Math.max(0, ship.fuel).toFixed(1)}`, 10, 40);

    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.6)';
      ctx.fillRect(0, 0, W, H);
      ctx.fillStyle = '#f00';
      ctx.font = '48px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over', W / 2, H / 2);
    }
  }

  let last = performance.now();
  function loop(now) {
    const dt = now - last;
    last = now;
    if (!gameOver) update(dt);
    draw();
    requestAnimationFrame(loop);
  }
  requestAnimationFrame(loop);
})();
